    +'<circle cx="230" cy="80" r="5" fill="#ff1744" stroke="#fff" stroke-width="1.6"/></g>'
    +'<path d="M195,38 A52,52 0 0 1 195,142 Z" fill="#10243e" opacity="0.55"/>'
    +'<circle cx="195" cy="90" r="52" fill="none" stroke="#eceff1" stroke-width="2"/>'
    +'<text x="163" y="24" fill="#ffe082" font-size="13.5" font-weight="bold">NGÀY</text>'
    +'<text x="228" y="24" fill="#90caf9" font-size="13.5" font-weight="bold">ĐÊM</text></svg>';
  if(t==='orbit') return open
    +'<rect width="320" height="180" fill="#0d2137"/>'
