    +'<text x="160" y="132" fill="#ffe082" font-size="13.5" font-weight="bold" text-anchor="middle">Mặt Trời</text>'
    +'<g><animateMotion dur="14s" repeatCount="indefinite" path="M42,92 a118,52 0 1,0 236,0 a118,52 0 1,0 -236,0"/>'
