    +'<text x="160" y="170" fill="#fff" font-size="13.5" text-anchor="middle">1 vòng quanh Mặt Trời = 365 ngày 6 giờ</text></svg>';
  if(t==='moon') return open
    +'<rect width="320" height="180" fill="#0d2137"/>'
    +'<circle cx="36" cy="34" r="1.8" fill="#fff"/><circle cx="292" cy="26" r="1.5" fill="#fff"/><circle cx="270" cy="130" r="1.8" fill="#fff"/><circle cx="52" cy="140" r="1.4" fill="#fff"/><circle cx="110" cy="20" r="1.3" fill="#fff"/>'
    +'<circle cx="160" cy="86" r="44" fill="#fdf6d8" stroke="#d7ccc8" stroke-width="2"/>'
