    +'<circle cx="36" cy="34" r="14" fill="#ffb300"/><g stroke="#ffb300" stroke-width="2.6" stroke-linecap="round"><line x1="36" y1="12" x2="36" y2="18"/><line x1="36" y1="50" x2="36" y2="56"/><line x1="14" y1="34" x2="20" y2="34"/><line x1="52" y1="34" x2="58" y2="34"/></g>'
