    +'<text x="222" y="18" fill="#37474f" font-size="13.5" font-weight="bold" text-anchor="middle">Ngưng tụ thành mây</text>'
    +'<g stroke="#1e88e5" stroke-width="3" stroke-linecap="round">'
    +'<line x1="192" y1="80" x2="188" y2="94"><animate attributeName="y1" values="78;92;78" dur="1.4s" repeatCount="indefinite"/><animate attributeName="y2" values="92;106;92" dur="1.4s" repeatCount="indefinite"/></line>'
    +'<line x1="222" y1="80" x2="218" y2="94"><animate attributeName="y1" values="78;92;78" dur="1.4s" begin="-0.45s" repeatCount="indefinite"/><animate attributeName="y2" values="92;106;92" dur="1.4s" begin="-0.45s" repeatCount="indefinite"/></line>'
    +'<line x1="252" y1="80" x2="248" y2="94"><animate attributeName="y1" values="78;92;78" dur="1.4s" begin="-0.9s" repeatCount="indefinite"/><animate attributeName="y2" values="92;106;92" dur="1.4s" begin="-0.9s" repeatCount="indefinite"/></line></g>'
    +'<text x="282" y="98" fill="#1565c0" font-size="13.5" font-weight="bold">Mưa</text>'
    +'<path d="M0,142 q20,-14 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 L320,180 L0,180 Z" fill="#42a5f5"/>'
    +'<path d="M262,128 C210,142 130,142 76,130" stroke="#2e7d32" stroke-width="4" fill="none" stroke-dasharray="8 6"><animate attributeName="stroke-dashoffset" from="28" to="0" dur="1.3s" repeatCount="indefinite"/></path>'
    +'<polygon points="66,128 82,124 80,138" fill="#2e7d32"/>'
    +'<text x="160" y="174" fill="#1b5e20" font-size="13.5" font-weight="bold" text-anchor="middle">Nước chảy thành sông → về biển</text></svg>';
  if(t==='wave') return open
    +'<rect width="320" height="180" fill="#b3e5fc"/>'
    +'<circle cx="284" cy="30" r="14" fill="#ffb300"/>'
    +'<g><animateTransform attributeName="transform" type="translate" from="0 0" to="-80 0" dur="2.4s" repeatCount="indefinite"/>'
    +'<path d="M0,108 q20,-20 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 L640,180 L0,180 Z" fill="#0288d1" opacity="0.75"/></g>'
    +'<g><animateTransform attributeName="transform" type="translate" from="-80 0" to="0 0" dur="3.8s" repeatCount="indefinite"/>'
    +'<path d="M0,132 q20,-16 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 L640,180 L0,180 Z" fill="#01579b" opacity="0.4"/></g>'
